388	   * @param {string} authMethod
389	   * @returns {string|null}
390	   */
391	  getEndSessionUrl(req, idToken, authMethod) {
392	    const client = this.getClient()
393	
394	    if (client.issuer.end_session_endpoint && client.issuer.end_session_endpoint.length > 0) {
395	      let postLogoutRedirectUri = null
396	
397	      if (authMethod === 'openid') {
398	        const { origin } = getRequestOrigin(req)
399	        // TODO: ABS does currently not support subfolders for installation
400	        // If we want to support it we need to include a config for the serverurl
401	        postLogoutRedirectUri = `${origin}${global.RouterBasePath}/login`
402	      }
403	      // else for openid-mobile we keep postLogoutRedirectUri on null
404	      //  nice would be to redirect to the app here, but for example Authentik does not implement
405	      //  the post_logout_redirect_uri parameter at all and for other providers
406	      //  we would also need again to implement (and even before get to know somehow for 3rd party apps)
407	      //  the correct app link like audiobookshelf://login (and maybe also provide a redirect like mobile-redirect).
408	      //   Instead because its null (and this way the parameter will be omitted completly), the client/app can simply append something like
409	      //  &post_logout_redirect_uri=audiobookshelf://login to the received logout url by itself which is the simplest solution
410	      //   (The URL needs to be whitelisted in the config of the SSO/ID provider)
411	
412	      return client.endSessionUrl({
