519	      // which browsers resolve to a cross-origin absolute URL.
520	      if (callbackUrl.startsWith('//') || callbackUrl.startsWith('/\\')) {
521	        Logger.warn(`[OidcAuth] Rejected protocol-relative callback URL: ${callbackUrl}`)
522	        return false
523	      }
524	
525	      const { origin: serverOrigin } = getRequestOrigin(req)
526	      const resolvedUrl = callbackUrl.startsWith('/') ? new URL(callbackUrl, serverOrigin) : new URL(callbackUrl)
527	
528	      if (resolvedUrl.origin !== serverOrigin) {
529	        Logger.warn(`[OidcAuth] Rejected callback URL to different origin: ${callbackUrl} (expected ${serverOrigin})`)
530	        return false
