540	        Logger.warn(`[OidcAuth] Rejected callback URL outside router base path: ${callbackUrl}`)
541	        return false
542	      }
543	
544	      return true
545	    } catch (error) {
546	      Logger.error(`[OidcAuth] Invalid callback URL format: ${callbackUrl}`, error)
547	      return false
548	    }
