  9	/**
 10	 * Local authentication strategy using username/password
 11	 */
 12	class LocalAuthStrategy {
 13	  constructor() {
 14	    this.name = 'local'
 15	    this.strategy = null
 16	  }
 17	
 18	  /**
 19	   * Get the passport strategy instance
 20	   * @returns {LocalStrategy}
 21	   */
 22	  getStrategy() {
 23	    if (!this.strategy) {
 24	      this.strategy = new LocalStrategy({ passReqToCallback: true }, this.verifyCredentials.bind(this))
 25	    }
 26	    return this.strategy
 27	  }
 28	
 29	  /**
 30	   * Initialize the strategy with passport
 31	   */
 32	  init() {
 33	    passport.use(this.name, this.getStrategy())
 34	  }
 35	
 36	  /**
 37	   * Remove the strategy from passport
 38	   */
 39	  unuse() {
 40	    passport.unuse(this.name)
 41	    this.strategy = null
 42	  }
 43	
 44	  /**
 45	   * Verify user credentials
 46	   * @param {import('express').Request} req
 47	   * @param {string} username
 48	   * @param {string} password
 49	   * @param {Function} done - Passport callback
 50	   */
 51	  async verifyCredentials(req, username, password, done) {
 52	    // Load the user given it's username
 53	    const user = await Database.userModel.getUserByUsername(username.toLowerCase())
 54	
 55	    if (!user?.isActive) {
 56	      if (user) {
 57	        this.logFailedLoginAttempt(req, user.username, 'User is not active')
 58	      } else {
 59	        this.logFailedLoginAttempt(req, username, 'User not found')
 60	      }
 61	      done(null, null)
 62	      return
 63	    }
 64	
 65	    // Check passwordless root user
 66	    if (user.type === 'root' && !user.pash) {
 67	      if (password) {
 68	        // deny login
 69	        this.logFailedLoginAttempt(req, user.username, 'Root user has no password set')
 70	        done(null, null)
 71	        return
 72	      }
 73	      // approve login
 74	      Logger.info(`[LocalAuth] User "${user.username}" logged in from ip ${requestIp.getClientIp(req)}`)
 75	
 76	      done(null, user)
 77	      return
 78	    } else if (!user.pash) {
 79	      this.logFailedLoginAttempt(req, user.username, 'User has no password set. Might have been created with OpenID')
 80	      done(null, null)
 81	      return
 82	    }
 83	
 84	    // Check password match
 85	    const compare = await bcrypt.compare(password, user.pash)
 86	    if (compare) {
 87	      // approve login
 88	      Logger.info(`[LocalAuth] User "${user.username}" logged in from ip ${requestIp.getClientIp(req)}`)
 89	
 90	      done(null, user)
 91	      return
 92	    }
 93	
 94	    // deny login
 95	    this.logFailedLoginAttempt(req, user.username, 'Invalid password')
 96	    done(null, null)
 97	  }
 98	
 99	  /**
100	   * Log failed login attempts
101	   * @param {import('express').Request} req
102	   * @param {string} username
103	   * @param {string} message
104	   */
105	  logFailedLoginAttempt(req, username, message) {
106	    if (!req || !username || !message) return
107	    Logger.error(`[LocalAuth] Failed login attempt for username "${username}" from ip ${requestIp.getClientIp(req)} (${message})`)
108	  }
109	
110	  /**
111	   * Hash a password with bcrypt
112	   * @param {string} password
113	   * @returns {Promise<string>} hash
114	   */
115	  hashPassword(password) {
116	    return new Promise((resolve) => {
117	      bcrypt.hash(password, 8, (err, hash) => {
118	        if (err) {
119	          resolve(null)
120	        } else {
121	          resolve(hash)
122	        }
123	      })
124	    })
125	  }
126	
127	  /**
128	   * Compare password with user's hashed password
129	   * @param {string} password
130	   * @param {import('../models/User')} user
131	   * @returns {Promise<boolean>}
132	   */
133	  comparePassword(password, user) {
134	    if (user.type === 'root' && !password && !user.pash) return true
135	    if (!password || !user.pash) return false
136	    return bcrypt.compare(password, user.pash)
137	  }
138	
139	  /**
140	   * Change user password
141	   * @param {import('../models/User')} user
142	   * @param {string} password
143	   * @param {string} newPassword
144	   */
145	  async changePassword(user, password, newPassword) {
146	    // Only root can have an empty password
147	    if (user.type !== 'root' && !newPassword) {
148	      return {
149	        error: 'Invalid new password - Only root can have an empty password'
150	      }
151	    }
152	
153	    // Check password match
154	    const compare = await this.comparePassword(password, user)
155	    if (!compare) {
156	      return {
157	        error: 'Invalid password'
158	      }
159	    }
160	
161	    let pw = ''
162	    if (newPassword) {
163	      pw = await this.hashPassword(newPassword)
164	      if (!pw) {
165	        return {
166	          error: 'Hash failed'
167	        }
168	      }
169	    }
170	
171	    try {
172	      await user.update({ pash: pw })
173	      Logger.info(`[LocalAuth] User "${user.username}" changed password`)
174	      return {
175	        success: true
176	      }
177	    } catch (error) {
178	      Logger.error(`[LocalAuth] User "${user.username}" failed to change password`, error)
179	      return {
180	        error: 'Unknown error'
181	      }
182	    }
183	  }
184	}
