220	class HlsRouter {
221	  constructor(auth, playbackSessionManager) {
222	    this.auth = auth
223	    this.playbackSessionManager = playbackSessionManager
224	
225	    this.router = express()
226	    this.router.disable('x-powered-by')
227	    this.init()
228	  }
229	
230	  init() {
231	    this.router.get('/:stream/:file', this.streamFileRequest.bind(this))
232	  }
233	
234	  parseSegmentFilename(filename) {
235	    var basename = Path.basename(filename, Path.extname(filename))
236	    var num_part = basename.split('-')[1]
237	    return Number(num_part)
238	  }
239	
240	  /**
241	   * Ensure filepath is inside streamDir
242	   * Used to prevent arbitrary file reads
243	   * @see https://nodejs.org/api/path.html#pathrelativefrom-to
244	   * 
245	   * @param {string} streamDir 
246	   * @param {string} filepath 
247	   * @returns {boolean}
248	   */
249	  validateStreamFilePath(streamDir, filepath) {
250	    const relative = Path.relative(streamDir, filepath)
251	    return relative && !relative.startsWith('..') && !Path.isAbsolute(relative)
252	  }
253	
254	  /**
255	   * GET /hls/:stream/:file
256	   * File must have extname .ts or .m3u8
257	   * 
258	   * @param {express.Request} req 
259	   * @param {express.Response} res 
260	   */
261	  async streamFileRequest(req, res) {
262	    const streamId = req.params.stream
263	    // Ensure stream is open
264	    const stream = this.playbackSessionManager.getStream(streamId)
265	    if (!stream) {
266	      Logger.error(`[HlsRouter] Stream "${streamId}" does not exist`)
267	      return res.sendStatus(404)
268	    }
269	
270	    // Ensure stream filepath is valid
271	    const streamDir = Path.join(this.playbackSessionManager.StreamsPath, streamId)
272	    const fullFilePath = Path.join(streamDir, req.params.file)
273	    if (!this.validateStreamFilePath(streamDir, fullFilePath)) {
274	      Logger.error(`[HlsRouter] Invalid file parameter "${req.params.file}"`)
275	      return res.sendStatus(400)
276	    }
277	
278	    const fileExt = Path.extname(req.params.file)
279	    if (fileExt !== '.ts' && fileExt !== '.m3u8') {
280	      Logger.error(`[HlsRouter] Invalid file parameter "${req.params.file}" extname. Must be .ts or .m3u8`)
281	      return res.sendStatus(400)
282	    }
283	
284	    if (!(await fs.pathExists(fullFilePath))) {
285	      Logger.warn('File path does not exist', fullFilePath)
286	
287	      if (fileExt === '.ts') {
288	        const segNum = this.parseSegmentFilename(req.params.file)
289	
290	        if (stream.isResetting) {
291	          Logger.info(`[HlsRouter] Stream ${streamId} is currently resetting`)
292	        } else {
293	          const startTimeForReset = await stream.checkSegmentNumberRequest(segNum)
294	          if (startTimeForReset) {
295	            // HLS.js will restart the stream at the new time
296	            Logger.info(`[HlsRouter] Resetting Stream - notify client @${startTimeForReset}s`)
297	            SocketAuthority.emitter('stream_reset', {
298	              startTime: startTimeForReset,
299	              streamId: stream.id
300	            })
301	          }
302	        }
303	      }
304	      return res.sendStatus(404)
305	    }
306	
307	    res.sendFile(fullFilePath)
308	  }
309	}
