220	class HlsRouter {
221	  constructor(auth, playbackSessionManager) {
222	    this.auth = auth
223	    this.playbackSessionManager = playbackSessionManager
224	
225	    this.router = express()
226	    this.router.disable('x-powered-by')
227	    this.init()
228	  }
