import type { FileMetadataJSON } from '../types'

class FileMetadata {
  declare filename: string
  declare ext: string
  declare path: string
  declare relPath: string
  declare size: number
  declare mtimeMs: number
  declare ctimeMs: number
  declare birthtimeMs: number
  declare wasModified: boolean

  constructor(metadata?: Partial<FileMetadataJSON> | null) {
    // Fields start as null until construct/setData; typed non-null as the JS reads them without null checks
    this.filename = null as unknown as string
    this.ext = null as unknown as string
    this.path = null as unknown as string
    this.relPath = null as unknown as string
    this.size = null as unknown as number
    this.mtimeMs = null as unknown as number
    this.ctimeMs = null as unknown as number
    this.birthtimeMs = null as unknown as number

    if (metadata) {
      this.construct(metadata)
    }

    // Temp flag used in scans
    this.wasModified = false
  }

  construct(metadata: Partial<FileMetadataJSON>) {
