import json,glob,os,sys
from datetime import datetime
def load(path):
    out=[]
    for line in open(path):
        try: out.append(json.loads(line))
        except: pass
    return out
for f in sorted(glob.glob('*.jsonl'), key=os.path.getmtime):
    sid=f[:-6]
    files=[f]+glob.glob(f'{sid}/**/*.jsonl', recursive=True)
    seen={}; ts=[]; branches=set(); models={}; first=None; userturns=0
    for p in files:
        for r in load(p):
            t=r.get('timestamp')
            if t: ts.append(t)
            if r.get('gitBranch'): branches.add(r['gitBranch'])
            m=r.get('message') or {}
            if r.get('type')=='user' and p==f and not r.get('isSidechain') and isinstance(m.get('content'),str):
                userturns+=1
                if first is None: first=m['content'][:110].replace('\n',' ')
            if r.get('type')=='assistant' and m.get('usage'):
                key=(p, m.get('id') or r.get('uuid'))
                seen[key]=(m.get('model'), m['usage'])
    tot={'in':0,'cw':0,'cr':0,'out':0}
    for model,u in seen.values():
        models[model]=models.get(model,0)+1
        tot['in']+=u.get('input_tokens',0); tot['cw']+=u.get('cache_creation_input_tokens',0)
        tot['cr']+=u.get('cache_read_input_tokens',0); tot['out']+=u.get('output_tokens',0)
    ts.sort()
    print(f"== {sid[:8]} {ts[0][:16]} -> {ts[-1][:16]} branches={sorted(branches)} subfiles={len(files)-1} userturns={userturns}")
    print(f"   models={models}")
    print(f"   in={tot['in']:,} cache_write={tot['cw']:,} cache_read={tot['cr']:,} out={tot['out']:,}")
    print(f"   first: {first}")
EOF
